const text = $input.first().json.text;

// ===== TRACKING NUMBERS =====
const trackingNumbers = text.match(/1Z[A-Z0-9]{16}|\b\d{10,15}\b/g) || [];
const filteredTracking = trackingNumbers.filter(t => {
  if (t.length < 10) return false;
  if (/^7\d{11,12}$/.test(t)) return false;
  if (/^[0-9]{10}$/.test(t) && parseInt(t) < 1000000000) return false;
  const escaped = t.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  if (new RegExp(`[(/]${escaped}[)/]`).test(text)) return false;
  return true;
});

const hasUPS = filteredTracking.some(t => t.startsWith('1Z'));
const hasFedEx = filteredTracking.some(t => !t.startsWith('1Z'));
let carrier = 'Unknown';
if (hasUPS && !hasFedEx) carrier = 'UPS Ground';
else if (hasFedEx && !hasUPS) carrier = 'FedEx Freight';
else if (hasUPS && hasFedEx) carrier = 'UPS Ground + FedEx Freight';

const trackingLinks = filteredTracking.map(t => {
  if (t.startsWith('1Z')) return `https://www.ups.com/track?tracknum=${t}`;
  else return `https://www.fedexfreight.com/fedextrack/?trknbr=${t}&trkqual=~${t}~FDFR`;
}).join('\n');

let shipToCompany = null;
let shipToContact = null;
let customerName = null;

const excludedNames = [
  'L2 Global', 'Larry Legend', 'Fanatics', 'Matt Lane',
  'Remit To', 'UPS', 'FedEx', 'USPS', 'Ground', 'Freight',
  'Express', 'Priority', 'Pallet', 'Prepaid', 'TAMPA', 'PAGE',
  'Invoice', 'Date', 'Customer ID', 'BILL TO', 'SHIP TO', 'Shalom Laber'
];

function isExcluded(name) {
  if (!name) return true;
  const lower = name.toLowerCase();
  return excludedNames.some(e => lower.includes(e.toLowerCase()));
}

function cleanName(name) {
  if (!name) return null;
  let c = name.replace(/^(UPS|FedEx|USPS|DHL|Pallet|Prepaid)\s*[-]?\s*(Ground|Freight|Express|Priority|2Day|Overnight)?\s*[-]?\s*/gi, '').trim();
  c = c.replace(/\s+(UW|NFL|NHL|MLB|NBA|Helmet|Jersey|Jrsy|Auto|Vol|Volume|II|I)\s*.*$/i, '').trim();
  c = c.replace(/\s+\d+$/, '').trim();
  return c || null;
}

const bizMatch = text.match(/([A-Z][A-Za-z0-9 '&.-]*(?:Breaks|Breakers|Cards|Sports|Shop|Collectibles|Trading|Hobby|Enterprises|Break))/i);
if (bizMatch && !isExcluded(bizMatch[1])) shipToCompany = bizMatch[1].trim();

const shipToMatch = text.match(/SHIP\s*TO[:\s]*\n+([^\n]+)/i);
if (shipToMatch) {
  let candidate = shipToMatch[1].trim();
  if (/^fanatics\//i.test(candidate)) candidate = candidate.split('/')[1].trim();
  if (!isExcluded(candidate)) shipToContact = candidate;
}

if (!shipToCompany && !shipToContact) {
  const poNameMatch = text.match(/([A-Za-z][A-Za-z0-9 '&.-]+?)\s+(?:UW|NFL|NHL|MLB|NBA)\s+/i);
  if (poNameMatch) {
    const n = cleanName(poNameMatch[1]);
    if (n && !isExcluded(n)) customerName = n;
  }
}

if (!shipToCompany && !shipToContact && !customerName) {
  const poFieldMatch = text.match(/CUSTOMER\s+P\.?O\.?\s*NO\.?[^\n]*\n([^\n]+)/i);
  if (poFieldMatch) {
    const poVal = poFieldMatch[1].trim();
    const nameBeforeProduct = poVal.match(/^([A-Za-z][A-Za-z0-9 '&.-]+?)\s+(?:UW|NFL|NHL|MLB|NBA|UW26|London|Photo|Bat|Jersey|Helmet)/i);
    if (nameBeforeProduct) {
      const n = cleanName(nameBeforeProduct[1]);
      if (n && !isExcluded(n)) customerName = n;
    } else if (!isExcluded(poVal)) {
      customerName = poVal;
    }
  }
}

let shipToName = shipToCompany || shipToContact || customerName;
if (shipToName) shipToName = cleanName(shipToName);

const invoiceMatch = text.match(/I(\d{8})/);
const invoiceNumber = invoiceMatch ? invoiceMatch[0] : null;

const productLines = [];
const barcodePattern = /\d{12,13}\s*\n([^\n]{10,})/g;
let barcodeMatch;
while ((barcodeMatch = barcodePattern.exec(text)) !== null) {
  const line = barcodeMatch[1].trim();
  if (!line.match(/^(TRACKING|TOTAL|SALES|SHIP|BILL|ORDER|PAGE|Remit)/i) && !line.match(/^\d+\.\d+$/) && line.length > 5) {
    productLines.push(line);
  }
}

const doNotOpenPattern = /\(DO NOT OPEN\)\s+([^\n]+)/gi;
let doNotOpenMatch;
while ((doNotOpenMatch = doNotOpenPattern.exec(text)) !== null) {
  const line = doNotOpenMatch[1].trim();
  if (!productLines.includes(line)) productLines.push(line);
}

const productDescription = productLines.length > 0 ? productLines.join(' / ') : null;

let qtyShipped = null;
const qtyMatch = text.match(/[A-Z0-9-]+\s+([\d.]+)\s+EA\s+([\d.]+)/);
if (qtyMatch) qtyShipped = parseFloat(qtyMatch[2]);

let orderTotal = null;
const totalMatch = text.match(/TOTAL\s*\n?\s*([\d,]+\.?\d*)/i);
if (totalMatch) orderTotal = parseFloat(totalMatch[1].replace(/,/g, ''));

const dateMatch = text.match(/(\d{1,2}\/\d{1,2}\/\d{4})/);
const orderDate = dateMatch ? dateMatch[0] : null;

if (carrier === 'Unknown' || carrier === 'UPS Ground') {
  if (/UPS\s+2\s+Day/i.test(text)) carrier = 'UPS 2 Day';
  else if (/UPS\s+Ground/i.test(text)) carrier = 'UPS Ground';
  else if (/FedEx\s+Freight/i.test(text)) carrier = 'FedEx Freight';
  else if (/FedEx/i.test(text)) carrier = 'FedEx';
}

return [{
  json: {
    customerName: shipToName,
    invoiceNumber,
    productDescription,
    qtyShipped,
    orderTotal,
    carrier,
    trackingLinks,
    trackingCount: filteredTracking.length,
    trackingNumbers: filteredTracking,
    orderDate
  },
  binary: $input.first().binary
}];

const taskId = $input.first().json.id;

// Try every upstream node in order — Gmail → Extract → Parse
// (binary can silently drop in separate-binary mode depending on test context)
let binary = null;

const sources = [
  'Gmail sees FWD email',
  'Extract from PDF',
  'Code in parse JavaScript reading the PDF'
];

for (const nodeName of sources) {
  try {
    const item = $(nodeName).first();
    if (item && item.binary && item.binary.attachment_0) {
      binary = item.binary;
      break;
    }
  } catch(e) {
    // node not accessible in this context, try next
  }
}

if (!binary) {
  throw new Error(
    'PDF binary (attachment_0) not found in any upstream node. ' +
    'FOR TESTING: click the Gmail trigger node → click "Fetch Test Event" → ' +
    'pick an email from info@l2global.com that has a PDF attached, THEN hit Execute Workflow. ' +
    'Do NOT just hit Execute Workflow without fetching a fresh test event first — ' +
    'pinned data does not preserve binary attachments.'
  );
}

return [{
  json: { id: taskId },
  binary: { attachment_0: binary.attachment_0 }
}];

// Build the internal ship-notification draft for Jasmine to copy/paste.
// Reads the parsed invoice data from the existing parse node.
// Format (matches how Jasmine already texts her coworker):
//   Customer- Qty Product
//   trackingnumber
//   trackingnumber

const taskId = $input.first().json.id;

let parsed = {};
try {
  parsed = $('Code in parse JavaScript reading the PDF').first().json || {};
} catch (e) {
  parsed = {};
}

const customer = (parsed.customerName || '').trim();
const product  = (parsed.productDescription || '').trim();
const qty      = parsed.qtyShipped;
const tracking = Array.isArray(parsed.trackingNumbers) ? parsed.trackingNumbers : [];

// Qty prefix only when we actually parsed one.
let qtyPart = '';
if (qty !== null && qty !== undefined && !isNaN(Number(qty)) && Number(qty) > 0) {
  qtyPart = String(Number(qty)) + ' ';
}

// Header line: "Hammer Breaks- 1 MLB Jersey"
const headerLeft  = customer || '[CUSTOMER — parse missed, fill in]';
const headerRight = (qtyPart + (product || '[PRODUCT — parse missed, fill in]')).trim();
const header = headerLeft + '- ' + headerRight;

// Bare tracking numbers, one per line, all in one message.
const trackingBlock = tracking.length
  ? tracking.join('\n')
  : '[NO TRACKING NUMBERS PARSED — check the invoice PDF]';

const draft = header + '\n' + trackingBlock;

// Flag anything that needs a human glance before sending.
const warnings = [];
if (!customer) warnings.push('customer name not parsed');
if (!product) warnings.push('product not parsed');
if (!tracking.length) warnings.push('no tracking numbers found');
if (qtyPart === '') warnings.push('qty not parsed');

const commentLines = [];
commentLines.push('SHIP DRAFT — copy the block below and send to coworker:');
commentLines.push('');
commentLines.push(draft);
commentLines.push('');
if (warnings.length) {
  commentLines.push('Check before sending: ' + warnings.join(', ') + '.');
} else {
  commentLines.push('All fields parsed cleanly.');
}

return [{
  json: {
    id: taskId,
    shipDraft: draft,
    shipDraftComment: commentLines.join('\n'),
    parseWarnings: warnings
  }
}];
